const ALLOWED_HOSTS = new Set(["127.0.0.1", "localhost"]);
export function proxy(req: Request) {
  const host = new URL(req.url).hostname;
  if (!ALLOWED_HOSTS.has(host)) return new Response(null, { status: 421 });
  return req;
}

